raw_counts = {
    (0, 0, 0): 168,
    (0, 1, 0): 252,
    (1, 0, 0): 36,
    (1, 1, 0): 144,
    (0, 0, 1): 96,
    (0, 1, 1): 24,
    (1, 0, 1): 168,
    (1, 1, 1): 112
}

conditional_probs = {}

# Calculate P(Y|X,Z)
for x_val in [0, 1]:
    for z_val in [0, 1]:
        # Denominator: count(X=x_val, Z=z_val)
        total_xz_count = 0
        for (x, y, z), count in raw_counts.items():
            if x == x_val and z == z_val:
                total_xz_count += count

        # Numerator: count(Y=1, X=x_val, Z=z_val)
        y1_xz_count = raw_counts.get((x_val, 1, z_val), 0)

        # P(Y=1 | X=x_val, Z=z_val)
        p_y1_given_xz = y1_xz_count / total_xz_count if total_xz_count > 0 else 0
        conditional_probs[f'P(Y=1|X={x_val},Z={z_val})'] = p_y1_given_xz

# Calculate P(Z)
total_overall_count = sum(raw_counts.values())
p_z = {}
for z_val in [0, 1]:
    total_z_count = 0
    for (x, y, z), count in raw_counts.items():
        if z == z_val:
            total_z_count += count
    p_z[f'P(Z={z_val})'] = total_z_count / total_overall_count if total_overall_count > 0 else 0

# Store P(Z) in conditional_probs dictionary as well for consistency
conditional_probs.update(p_z)

print(f'{conditional_probs=}')

